const hasActiveSubscription = (): boolean => {
  // Check if user has purchased any plan (stored in localStorage or has valid plan)
  const storedPlan = localStorage.getItem('userSubscriptionPlan');
  const hasPurchasedPlan = localStorage.getItem('hasPurchasedPlan') === 'true';
  return hasPurchasedPlan || (storedPlan && storedPlan !== 'FREE');
};

